/* Optional mm ruler: show only with debug_ruler=1 in printview URL */
.debug-ruler {
	position: absolute;
	inset: 0;
	z-index: 9999;
	pointer-events: none;
	background-image:
		linear-gradient(
			to right,
			rgba(255, 0, 0, 0.22) 0.15mm,
			transparent 0.15mm
		),
		linear-gradient(
			to bottom,
			rgba(255, 0, 0, 0.22) 0.15mm,
			transparent 0.15mm
		),
		linear-gradient(
			to right,
			rgba(0, 0, 255, 0.35) 0.2mm,
			transparent 0.2mm
		),
		linear-gradient(
			to bottom,
			rgba(0, 0, 255, 0.35) 0.2mm,
			transparent 0.2mm
		);
	background-size:
		1mm 1mm,
		1mm 1mm,
		10mm 10mm,
		10mm 10mm;
}
.debug-ruler::before {
	content: "mm ruler: red=1mm blue=10mm";
	position: absolute;
	top: 2mm;
	left: 2mm;
	padding: 1mm 2mm;
	background: rgba(255, 255, 255, 0.9);
	color: #c00;
	font-size: 8pt;
}
.debug-payment-box {
	position: absolute;
	left: 70mm;
	top: 248mm;
	width: 75mm;
	height: 32mm;
	border: 0.4mm dashed #f00;
	z-index: 10000;
	pointer-events: none;
}

.amount-words {
